// Generates src/generated/{schemas.ts,types.ts} from schemas/*.schema.json.
// Run via `npm run gen`. CI runs it and fails on a diff, so generated files
// are always committed in sync with the schemas.
import { readdir, readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import process from 'node:process';
import { compile } from 'json-schema-to-typescript';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const schemaDir = join(root, 'schemas');
const outDir = join(root, 'src', 'generated');

const banner = '/* GENERATED by packages/contract/scripts/gen.mjs from schemas/*.schema.json. Do not edit. */';

const files = (await readdir(schemaDir)).filter((f) => f.endsWith('.schema.json')).sort();
await mkdir(outDir, { recursive: true });

/** @type {{ key: string, title: string, schema: unknown }[]} */
const entries = [];
for (const f of files) {
  const schema = JSON.parse(await readFile(join(schemaDir, f), 'utf8'));
  const key = f.replace(/\.schema\.json$/, '');
  entries.push({ key, title: schema.title, schema });
}

// One module per schema: json-schema-to-typescript derives names for nested
// types from property names, which collide across schemas if concatenated.
for (const { key, title, schema } of entries) {
  const ts = await compile(schema, title, {
    bannerComment: banner,
    additionalProperties: false,
    style: { singleQuote: true },
  });
  await writeFile(join(outDir, `${key}.ts`), ts);
}

const typesIndex = [
  banner,
  ...entries.map(({ key, title }) => `export type { ${title} } from './${key}.js';`),
  '',
].join('\n');
await writeFile(join(outDir, 'types.ts'), typesIndex);

const schemasTs = [
  banner,
  '/* eslint-disable */',
  'export const schemas = {',
  ...entries.map(({ key, schema }) => `  ${JSON.stringify(key)}: ${JSON.stringify(schema, null, 2).replace(/\n/g, '\n  ')},`),
  '} as const;',
  '',
  'export type SchemaName = keyof typeof schemas;',
  '',
].join('\n');
await writeFile(join(outDir, 'schemas.ts'), schemasTs);

process.stdout.write(`generated ${entries.length} schemas\n`);
